package com.bananalab.lite;
import java.nio.*;import java.nio.charset.*;import java.io.*;
/** Only changes typed versionCode; package, permissions and resources remain intact. */
final class ApkManifest{
 static int u16(byte[] b,int p)throws IOException{if(p<0||p+2>b.length)throw new IOException("Manifest truncado.");return (b[p]&255)|((b[p+1]&255)<<8);}
 static int i32(byte[] b,int p)throws IOException{return u16(b,p)|(u16(b,p+2)<<16);}
 static int[] length(byte[] b,int p,boolean utf8)throws IOException{int a=utf8?b[p]&255:u16(b,p);if((a&(utf8?128:32768))==0)return new int[]{a,p+(utf8?1:2)};return new int[]{utf8?((a&127)<<8)|(b[p+1]&255):((a&32767)<<16)|u16(b,p+2),p+(utf8?2:4)};}
 static byte[] version(byte[] original,int next)throws IOException{byte[] b=original.clone();if(i32(b,0)!=0x00080003||i32(b,4)!=b.length)throw new IOException("Manifest binario inválido.");String[] strings=null;int changed=0;for(int p=8;p+8<=b.length;){int type=u16(b,p),head=u16(b,p+2),size=i32(b,p+4);if(size<head||size<8||p+size>b.length)throw new IOException("Chunk de manifest inválido.");if(type==1){int count=i32(b,p+8),flags=i32(b,p+16),start=i32(b,p+20);if(count<0||count>20000)throw new IOException("Strings de manifest fuera de límites.");strings=new String[count];for(int i=0;i<count;i++){int at=p+start+i32(b,p+head+i*4);boolean utf8=(flags&256)!=0;int[] len=length(b,at,utf8);if(utf8)len=length(b,len[1],true);int bytes=len[0]*(utf8?1:2);if(len[1]<p||len[1]+bytes>p+size)throw new IOException("String de manifest truncado.");strings[i]=new String(b,len[1],bytes,utf8?"UTF-8":"UTF-16LE");}}else if(type==0x0102&&strings!=null){int name=i32(b,p+20);if(name>=0&&name<strings.length&&strings[name].equals("manifest")){int start=u16(b,p+24),width=u16(b,p+26),count=u16(b,p+28);if(width<20)throw new IOException("Atributos de manifest inválidos.");for(int i=0;i<count;i++){int at=p+16+start+i*width;if(at+20>p+size)throw new IOException("Atributo truncado.");int id=i32(b,at+4);if(id>=0&&id<strings.length&&strings[id].equals("versionCode")){if((b[at+15]&255)!=16||next<=i32(b,at+16))throw new IOException("El código de versión debe aumentar.");ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN).putInt(at+16,next);changed++;}}}}p+=size;}if(changed!=1)throw new IOException("No identifiqué una única versión Android.");return b;}
}
